import { checkout, items } from './catalog';
const receipt = checkout(10);
console.log('R10_WEBSITE_APP', JSON.stringify({ names: items.map((item) => item.name), ...receipt }));
export default receipt;
import { subtotal, applyDiscount } from './math';
export interface Item { id: string; name: string; price: number; }
export const items: Item[] = [
  { id: 'book', name: 'Notebook', price: 12 },
  { id: 'pens', name: 'Pen set', price: 18 }
];
export function checkout(discount: number) {
  const before = subtotal(items.map((item) => item.price));
  return { itemCount: items.length, before, total: applyDiscount(before, discount) };
}
export function subtotal(prices: readonly number[]): number {
  return prices.reduce((sum, price) => sum + price, 0);
}
export function applyDiscount(value: number, percentage: number): number {
  if (percentage < 0 || percentage > 100) throw new RangeError('Discount must be between 0 and 100.');
  return Math.round(value * (100 - percentage)) / 100;
}

