  while (i < source.length) {
    const ch = source[i] ?? '';
    if (/\s/.test(ch)) { advance(); continue; }
    if (ch === '/' && source[i + 1] === '/') {
      while (i < source.length && source[i] !== '\n') advance();
      continue;
    }
    if (ch === '/' && source[i + 1] === '*') {
      const start = i; const sl = line; const sc = column;
      advance(2);
      while (i < source.length && !(source[i] === '*' && source[i + 1] === '/')) advance();
